BEGIN; CREATE TABLE IF NOT EXISTS pol_party_factions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), party_id UUID NOT NULL REFERENCES pol_parties(id) ON DELETE CASCADE, name VARCHAR(100) NOT NULL, ideology_lean JSONB NOT NULL DEFAULT '{}', demand_type VARCHAR(50) NOT NULL DEFAULT 'policy_axis', demand_payload JSONB NOT NULL DEFAULT '{}', loyalty INTEGER NOT NULL DEFAULT 70 CONSTRAINT pol_party_factions_loyalty_range CHECK (loyalty >= 0 AND loyalty <= 100), membership_share NUMERIC(4,3) NOT NULL DEFAULT 0.333, leader_character_id UUID, is_restless BOOLEAN NOT NULL DEFAULT FALSE, created_arc INTEGER NOT NULL, updated_arc INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS idx_pol_party_factions_party ON pol_party_factions(party_id); UPDATE company_finances cf SET available_cash = 50000000 FROM companies c WHERE cf.company_id = c.id AND c.is_npc = false AND cf.available_cash > 50000000; UPDATE character_finances cf SET cash_in_hand = 10000000 FROM characters c WHERE cf.character_id = c.id AND cf.cash_in_hand > 10000000; UPDATE share_price_history sph SET open_price = 50, close_price = 50, high_price = 50, low_price = 50, pe_ratio = 10 FROM companies c WHERE sph.company_id = c.id AND c.is_npc = false AND sph.close_price > 500; COMMIT;
